            introduction = "हामी दैनिक बोलिचालीमा 'मलाई थाहा छ' र 'म विश्वास गर्छु' भन्ने वाक्यहरूलाई उस्तै अर्थमा प्रयोग गर्छौँ। तर दर्शन र वास्तविकताको धरातलमा यी दुईबीच आकाश र पातालको फरक छ।",
            paragraphs = listOf(
                "मानिसको मनले अनिश्चितता मन पराउँदैन। जब हामी कुनै घटनाको कारण बुझ्दैनौँ—जस्तै चट्याङ किन पर्छ, रोग किन लाग्छ, वा मृत्युपछि के हुन्छ—तब हाम्रो मन खाली ठाउँ भर्न हतारिन्छ। प्रमाण नहुँदा पनि मनले कल्पनामा आधारित एउटा उत्तर बनाउँछ र त्यसलाई 'विश्वास' को नाम दिन्छ। विश्वासले मनलाई सान्त्वना त दिन्छ, तर के सान्त्वना दिनु र सत्य हुनु एउटै कुरा हो?",
                "एउटा साधारण उदाहरण हेरौँ। यदि मैले मेरो खल्तीमा हजार रुपैयाँको नोट छ भनेर उत्कट विश्वास गरेँ, आँखा चिम्लेर प्रार्थना गरेँ, र पूरै इमानदारीका साथ पत्याएँ भने पनि—जबसम्म वास्तवमा खल्तीमा नोट हुँदैन, मेरो विश्वासले चियाको पैसा तिर्न सक्दैन। वास्तविकता त्यो हो, जुन तपाईंले विश्वास गर्न छोड्दा पनि हराउँदैन; र भ्रम त्यो हो, जुन अस्तित्वमा रहनका लागि तपाईंको निरन्तर विश्वासको वैशाखी चाहिन्छ।",
                "हाम्रो समाजमा भावनात्मक अनुभूतिलाई नै प्रमाण मान्ने ठूलो चलन छ। कसैले भन्नुहुन्छ—'जब म मन्दिरमा आँखा चिम्लिन्छु, मलाई भित्रैदेखि आनन्द र ऊर्जाको अनुभूति हुन्छ, त्यसैले भगवान् हुनुहुन्छ भन्ने मलाई पक्का थाहा छ।' म उहाँको त्यो शान्तिको अनुभूतिलाई पूर्ण सम्मान गर्छु। उहाँले झूट बोलिरहनुभएको छैन। तर प्रश्न के हो भने—त्यो शान्तिको अनुभूति बाह्य दैवी शक्तिको प्रमाण हो कि मानिसको आफ्नै मस्तिष्कको मनोवैज्ञानिक अवस्था?",
                "संसारका विभिन्न धर्मका मानिसहरूले आ-आफ्ना परस्पर विरोधी देवताहरूको ध्यान गर्दा ठीक उस्तै शान्ति र अलौकिक अनुभूति पाउँछन्। संगीत सुन्दा, प्रकृतिको काखमा बस्दा वा विपश्यना ध्यान (जहाँ कुनै ईश्वरको कल्पना गरिँदैन) गर्दा पनि मस्तिष्कमा उही न्यूरो-केमिकल परिवर्तन र गहिरो शान्ति उत्पन्न हुन्छ। तसर्थ, मनको मीठो अनुभूति मानसिक स्वास्थ्यका लागि उपयोगी हुन सक्छ, तर त्यो ब्रह्माण्डको वस्तुनिष्ठ सत्यको प्रमाण बन्न सक्दैन।",
                "ज्ञान (Knowledge) निर्माण हुनका लागि प्रमाण, परीक्षण र दोहोर्याएर जाँच्न सकिने आधार चाहिन्छ। विज्ञानले जब 'पृथ्वी सूर्यको वरिपरि घुम्छ' भन्छ, उसले 'मेरो कुरा पत्याऊ नत्र पाप लाग्छ' भन्दैन। उसले दूरबीन दिन्छ, गणितीय सूत्र दिन्छ र भन्छ—'आफैं हिसाब गरेर हेर, यदि मेरो हिसाब गलत निस्कियो भने म आफ्नो सिद्धान्त फेर्न तयार छु।' यही गुणले ज्ञानलाई अन्धविश्वासभन्दा अलग बनाउँछ।",
                "तर विश्वास (Faith) को स्वभाव ठीक उल्टो हुन्छ। विश्वासले प्रमाण नभएको ठाउँमा प्रश्न नउठाउन आग्रह गर्छ। अझ कतिपय अवस्थामा त प्रमाणले गलत देखाउँदा-देखाउँदै पनि अडिग रहनुलाई 'गहिरो आस्था' भनेर प्रशंसा गरिन्छ। जब हठलाई नै सद्गुण मान्न थालिन्छ, तब मानिस र वास्तविकताबीचको दूरी कहिल्यै नमेटिने गरी बढ्दै जान्छ।",
                "हामीले इतिहासमा देखेका छौँ—कुनै समय मानिसहरू पृथ्वी चेप्टो छ भनेर पूर्ण विश्वास गर्थे। रोगहरूलाई बोक्सी वा प्रेतआत्माको खेल ठान्थे। ती विश्वासहरू पछाडि हजारौँ वर्षको परम्परा थियो, तर वास्तविकता अर्कै थियो। जब मानिसले विश्वासको सट्टा अवलोकन र प्रमाणलाई रोज्यो, तब मात्र बिफर र हैजाजस्ता महामारीबाट करोडौँ मानिसको ज्यान बचाउन सम्भव भयो।",
                "मैले आफ्नो सोच परिवर्तन गर्नुको एउटा मुख्य कारण यही दूरीलाई चिन्नु थियो। मैले आफैंसँग वाचा गरेँ—मलाई जे कुरा साँचो होस् जस्तो लाग्छ (Wishful thinking) र जे कुरा वास्तवमा प्रमाणित छ, ती दुईलाई म कहिल्यै मिसाउने छैन। सत्य कहिलेकाहीँ तितो वा अपूरो हुन सक्छ, तर काल्पनिक गुलियोभन्दा तितो यथार्थ नै मानिसको प्रगतिको साँचो जग हो।"
            ),
            reflectionQuestion = "कुनै कुराले मनलाई शान्ति वा सान्त्वना दिन्छ भन्दैमा के त्यो कुरा स्वतः सत्य प्रमाणित हुन्छ?",
            memorableQuote = "वास्तविकता त्यो हो जुन तपाईंले पत्याउन छोड्दा पनि अस्तित्वमा रहिरहन्छ; भ्रम त्यो हो जसलाई बाँचिरहन तपाईंको अन्धो विश्वासको वैशाखी चाहिन्छ।",
            references = listOf("David Hume — An Enquiry Concerning Human Understanding (1748)", "Bertrand Russell — The Problems of Philosophy (1912)"),
            readingTimeMinutes = 7
