        BookChapter(
            id = "ch_4",
            chapterNumber = 4,
            displayOrder = 6,
            partId = "part_1",
            badgeLabel = "अध्याय ४ • CHAPTER 4",
            title = "सबैले मानेको कुरा सत्य नै हुन्छ?",
            subtitle = "भीडको मनोविज्ञान, परम्पराको भार र बहुमतको भ्रम",
            introduction = "'यति धेरै मान्छे र हाम्रा हजारौँ वर्षदेखिका पुर्खाहरू के सबै मूर्ख थिए त?'—जब तपाईं परम्परागत मान्यतामाथि प्रश्न उठाउनुहुन्छ, यो प्रश्न हतियार बनेर तपाईंको अगाडि तेर्सिन्छ।",
            paragraphs = listOf(
                "मानिस एक सामाजिक प्राणी हो। आदिम कालमा जङ्गलमा बाँच्दा समूहबाट एक्लिनुको अर्थ मृत्यु हुन्थ्यो। त्यसैले हाम्रो विकासक्रम (Evolution) ले नै हामीभित्र समूहसँग मिलेर बस्ने र समूहको विचारमा सहमति जनाउने गहिरो प्रवृत्ति विकास गरिदियो। मनोविज्ञानमा यसलाई 'कन्फर्मिटी' (Conformity) भनिन्छ। भीडको बीचमा उभिएर 'तपाईंहरू गलत हुनुहुन्छ' भन्नुभन्दा भीडसँगै ताली बजाउनु हजार गुणा सजिलो र सुरक्षित हुन्छ।",
                "तर तर्कशास्त्रमा एउटा प्रसिद्ध नियम छ, जसलाई 'अर्ग्युमेन्टम एड पपुलम' (Argumentum ad populum) वा बहुमतको तर्क भनिन्छ। यसले भन्छ—कुनै कुरा करोडौँ मानिसले पत्याउँदैमा वा हजारौँ वर्षदेखि मानिँदै आउँदैमा त्यो स्वतः सत्य हुँदैन। सत्यको फैसला मतदानबाट वा टाउको गनेर हुँदैन।",
                "हाम्रै इतिहासका पानाहरू पल्टाएर हेरौँ। केही शताब्दीअघिसम्म हाम्रो समाजमा 'सती प्रथा' प्रचलित थियो। लोग्नेको मृत्युपछि जिउँदो स्वास्नीलाई चितामा राखेर जलाइन्थ्यो, र वरिपरि उभिएको पूरै समाजले त्यसलाई 'पवित्र धर्म' र 'सतीत्वको सर्वोच्च रूप' मानेर जयजयकार गर्थ्यो। चितामा जलेकी महिलाको चित्कार नसुवियोस् भनेर ढोल र शङ्ख बजाइन्थ्यो। त्यतिबेला बहुमत कसको पक्षमा थियो? परम्परा कसको पक्षमा थियो? निश्चय नै सती प्रथाको पक्षमा। तर के बहुमतले मान्दैमा निर्दोष महिलालाई जिउँदै जलाउनु सत्य र नैतिक कार्य थियो त?",
                "त्यस्तै, दास प्रथा हजारौँ वर्षसम्म संसारभरि सामान्य मानिन्थ्यो। जातीय छुवाछुतलाई पुस्तौँदेखि समाजको बहुमतले ईश्वरीय नियम मानेर स्वीकार गर्यो। ग्यालिलियोले जब पृथ्वी घुम्छ भने, त्यतिबेलाको पूरै धार्मिक र सामाजिक सत्ता उनको विरुद्धमा थियो। एकजना मानिस एकतिर र पूरै संसार अर्कोतिर हुँदा पनि सत्य त ग्यालिलियोकै दूरबीनमा थियो, भीडको नारामा थिएन।",
                "पुर्खाहरूको अनुभवको सम्मान गर्नु र पुर्खाहरूको अज्ञानतालाई पूजा गर्नु दुई बिल्कुलै फरक कुरा हुन्। हाम्रा पुर्खाहरूले आफ्ना समयका सीमाभित्र रहेर बाँच्नका लागि जे जाने, त्यही गरे। उनीहरूसँग आजको जस्तो सूक्ष्मदर्शक यन्त्र, अन्तरिक्ष यान, चिकित्सा विज्ञान र विश्वव्यापी मानव अधिकारको चेतना थिएन। यदि आज हाम्रा पुर्खाहरू फर्किएर आउने हो भने, हामीले अझै पनि उनीहरूका पुराना गल्तीहरूलाई नै 'परम्परा' भन्दै बोकेर हिँडेको देखेर सायद उनीहरू आफैं लज्जित हुने थिए।",
                "परम्परा भनेको बगिरहेको नदीजस्तो हुनुपर्छ, जसमा समयसँगै नयाँ मुहानका सफा पानीहरू थपिन्छन् र फोहोरहरू किनारा लाग्छन्। तर जब परम्परालाई जमेको पोखरीजस्तो बनाइन्छ, तब त्यसमा काइ लाग्छ र दुर्गन्ध फैलिन थाल्छ। 'पहिलेदेखि चलिआएको' भन्नु कुनै कार्य जारी राख्नका लागि पर्याप्त कारण हुनै सक्दैन।",
                "मैले जब यो सत्य बुझेँ, तब भीडको संख्याले मलाई तर्साउन छोड्यो। मैले बुझेँ कि लाखौँ मानिसले एउटै भ्रम पाले पनि त्यो भ्रम नै रहन्छ, र एकजना मात्र मानिसले प्रमाण र मानवीय करुणाका साथ सत्य बोल्यो भने पनि त्यो सत्य नै रहन्छ।",
                "स्वतन्त्र सोचको अर्थ समाजबाट भाग्नु होइन; बरु समाजभित्रै बसेर समाजलाई अझ न्यायपूर्ण र विवेकशील बनाउनका लागि गलत बहुमतसँग असहमत हुने साहस राख्नु हो।"
            ),
            reflectionQuestion = "हाम्रो समाजमा आज पनि 'सबैले मान्दै आएको चलन' भन्दै जोगाइएका कुन-कुन अभ्यासहरू भविष्यको पुस्ताले अन्धविश्वास र अन्याय ठान्नेछ?",
            memorableQuote = "लाखौँ मानिसले एउटै भ्रम पाले पनि त्यो भ्रम नै रहन्छ; सत्यको फैसला भीडको टाउको गनेर हुँदैन, प्रमाण र मानवीय विवेकले हुन्छ।",
